content.text:
{
  "primary_meaning": "The covenant people of God, fulfilled or continued as the Christian Church (spiritual/new Israel)",
  "primary_basis": [
    "Galatians 6:16",
    "Romans 9:6-8",
    "Romans 2:28-29",
    "1 Peter 2:9-10",
    "Matthew 21:43",
    "Ephesians 2:11-22",
    "Hosea 1:10 / 2:23 (applied to Gentile believers in Romans 9:25-26 and 1 Peter 2:10)"
  ],
  "alternatives": [
    {
      "meaning": "The ethnic/physical descendants of Jacob (the Jewish people) remaining distinct as God's chosen people",
      "basis": [
        "Genesis 32:28",
        "Romans 11:1-29",
        "Jeremiah 31:35-37",
        "OT covenant promises taken as irrevocable to ethnic Israel"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Jesus Christ himself as the true/faithful Israel in whom the nation's vocation is fulfilled",
      "basis": [
        "Matthew 2:15 (Hosea 11:1)",
        "Isaiah servant songs applied to Christ",
        "John 15:1 (true vine)"
      ],
      "prominence": "common"
    },
    {
      "meaning": "The modern geopolitical State of Israel as prophetic fulfillment",
      "basis": [
        "Ezekiel 36–37",
        "Isaiah 11:11-12",
        "Amos 9:14-15 (read as national restoration)"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "All true believers (Jew and Gentile) without strong ecclesiological identification as 'Church as Israel'",
      "basis": [
        "Galatians 3:7-29",
        "Romans 4"
      ],
      "prominence": "common"
    }
  ],
  "has_settled_consensus": false,
  "confidence": "high",
  "notes": "Christian interpretation of 'Israel' is sharply divided along theological lines (covenant theology/supersessionism vs. dispensationalism vs. dual-covenant views). The Church-as-true-Israel reading has deep roots in patristic, medieval, Reformation, and much mainline teaching and remains widely recognizable as the historic symbolic default, yet competing literal-ethnic and Christological readings are also longstanding and currently influential; no single symbolic sense commands universal agreement."
}
